  const cards = Array.from(document.querySelectorAll('.vehicle-card, phx-component[data-cy="vehicle-card"], div[class*="vehicle-card"]'));
  if (cards.length === 0) {
    // try fallback
    const articles = Array.from(document.querySelectorAll('article, div[id*="listing"]'));
    return { count: 0, text: document.body.innerText.slice(0, 2000) };
  }
  return {
    count: cards.length,
    listings: cards.map(c => {
      const a = c.querySelector('a.vehicle-card-link') || c.querySelector('a[href*="/vehicledetail/"]') || c.querySelector('a');
      return {
        text: c.innerText.slice(0, 300),
        href: a?.href
      };
    })
  };
});
