const comparisonData = await browserjs(tabId, () => {
  // Let's get all comparison rows or text
  const tables = Array.from(document.querySelectorAll('table, [class*="table"], [class*="comparison"], [class*="spec"]'));

  // Extract all text sections
  const rows = Array.from(document.querySelectorAll('tr, div[class*="row"], div[class*="specRow"]')).map(r => r.innerText?.trim()).filter(Boolean);

  return {
