const tabId = 2052873101;
// Click "Show more features" if present and get full specs table
const specs = await browserjs(tabId, () => {
  const showMoreBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText?.includes('Show more features'));
  if (showMoreBtn) showMoreBtn.click();

  // Extract all rows from tables or spec containers
  const items = Array.from(document.querySelectorAll('[class*="specRow"], [class*="featureRow"], tr')).map(row => {
    return Array.from(row.children).map(c => c.innerText?.trim()).filter(Boolean);
  }).filter(arr => arr.length >= 2);

  return {
    items,
    bodyText: document.body.innerText
